public static void main(String[] args) {
    try (Scanner sc = new Scanner(System.in)) {
        int N = sc.nextInt();

        int[] stock = new int[N];
        int[] A = new int[N];
        int[] B = new int[N];

        for (int i = 0; i < N; i++) {
            stock[i] = sc.nextInt();
        }
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
        }
        for (int i = 0; i < N; i++) {
            B[i] = sc.nextInt();
        }

        int maxServings = 0;

        for (int servingsA = 0; ; servingsA++) {
            boolean canMakeA = true;
            for (int i = 0; i < N; i++) {
                if (servingsA * A[i] > stock[i]) {
                    canMakeA = false;
                    break;
                }
            }
            if (!canMakeA) break;

            int maxServingsB = Integer.MAX_VALUE;
            for (int i = 0; i < N; i++) {
                int remainingStock = stock[i] - servingsA * A[i];
                maxServingsB = Math.min(maxServingsB, remainingStock / B[i]);
            }

            maxServings = Math.max(maxServings, servingsA + maxServingsB);
        }

        System.out.println(maxServings);
    }
}
